<?php
declare(strict_types=1);
namespace EPejabat\Core;
final class UpgradeWeb {
 private static function raw(string $name,int $max=72):string {$v=$_POST[$name]??'';if(!is_string($v)||strlen($v)>$max||str_contains($v,"\0"))throw new \InvalidArgumentException('Input tidak sah.');return $v;}
 private static function keyField(string $name,string $label):string {return '<label>'.Support::escape($label).'<input type="password" name="'.$name.'" inputmode="numeric" pattern="[0-9]{12}" minlength="12" maxlength="12" autocomplete="off" required></label>';}
 private static function fresh(?array $report):bool {$at=strtotime($report['checked_at']??'');return $at!==false&&$at<=time()+60&&time()-$at<600&&($report['decision']??'')==='BASELINE MATCH';}
 public static function handle(\PDO $p,?array $user,string $public):never {
  header('Cache-Control: no-store, private, max-age=0');if(!$user)Support::redirect('/login');$u=(int)$user['id'];if(!Authorization::super($p,$u)){http_response_code(403);Support::layout('Upgrade Manager','<p>Akses Super Admin aktif diperlukan.</p>');}
  $manager=new LiveUpgradeManager($p,$u,$public);$error='';$result='';
  if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
   Support::checkCsrf();$action=self::raw('action',40);$id=self::raw('run_id',32);
   if($action==='key_setup'){InstallationKey::setup($p,$u,self::raw('key'),self::raw('key_confirm'),self::raw('password'));$result='<p role="status">Installation Key berjaya ditetapkan. Sahkan kod untuk membuka upgrade.</p>';}
   elseif($action==='key_verify'){InstallationKey::verify($p,$u,self::raw('key'));$result='<p role="status">Kebenaran upgrade diberikan selama 10 minit. Pakej staged dikekalkan.</p>';}
   elseif($action==='key_rotate'){InstallationKey::rotate($p,$u,self::raw('old_key'),self::raw('key'),self::raw('key_confirm'),self::raw('password'));$result='<p role="status">Installation Key ditukar. Kod dan kebenaran sesi lama tidak lagi sah.</p>';}
   elseif($action==='key_reset'){InstallationKey::reset($p,$u,self::raw('recovery_token',64),self::raw('key'),self::raw('key_confirm'),self::raw('password'),self::raw('reason',500));$result='<p role="status">Installation Key dipulihkan. Sahkan kod baharu.</p>';}
   else {
    InstallationKey::requireAuthorization($p,$u);
    if($action==='baseline_verify'){$report=ProductionBaseline::browserVerify($p,$u);$_SESSION['baseline_verification']=$report;$result='<p role="status">Pengesahan baseline: '.Support::escape($report['verification']['decision']).'. Ini pengesahan metadata; polisi pemasangan dan preflight pakej masih wajib.</p>';}
    elseif($action==='baseline_generate'){$baseline=ProductionBaseline::capture($p,$u);$result='<p role="status">Baseline metadata berjaya dijana. Tiada source, credentials atau data staf dieksport.</p>';}
    elseif($action==='baseline_download'){$baseline=ProductionBaseline::latest($p,$u);header('Content-Type: application/json');header('Content-Disposition: attachment; filename="epejabat-production-baseline.json"');echo json_encode($baseline,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR);exit;}
    elseif($action==='release_configure'){ReleaseDelivery::configure($p,$u,self::raw('catalog_url',1000),self::raw('package_base',1000),self::raw('password'));$result='<p role="status">Release repository dikonfigurasi; publisher signature kekal wajib.</p>';}
    elseif($action==='release_catalog'){$_SESSION['release_catalog']=ReleaseDelivery::catalog($p,$u);$result='<p role="status">Catalog release bertandatangan disahkan.</p>';}
    elseif($action==='release_retrieve'){$s=ReleaseDelivery::retrieve($p,$u,self::raw('module',30),self::raw('version',30));$id=$s['id'];$_SESSION['upgrade_active_run']=$id;$action='preflight';}
    if($action==='upload'){$f=$_FILES['package']??null;if(!is_array($f)||($f['error']??-1)!==UPLOAD_ERR_OK||($f['size']??0)>33554432||!is_uploaded_file($f['tmp_name']??''))throw new \RuntimeException('Upload ZIP gagal; semak had upload hosting.');$s=$manager->stageAutomatic($f['tmp_name']);$id=$s['id'];$_SESSION['upgrade_active_run']=$id;$action='preflight';}
    if(in_array($action,['baseline_verify','baseline_generate','release_configure','release_catalog'],true)){}
    elseif($action==='select'){ $manager->state($id);$_SESSION['upgrade_active_run']=$id; }
    elseif($action==='new_package'){unset($_SESSION['upgrade_active_run']);$_SESSION['upgrade_new_package']=true;}
    elseif($action==='preflight'){
     unset($_SESSION['upgrade_once'][$id]);$_SESSION['upgrade_active_run']=$id;$report=$manager->report($id);if(!self::fresh($report))$report=$manager->preflight($id);
     if(($report['decision']??'')==='BASELINE MATCH'){$ready=$manager->backupReadiness();$_SESSION['upgrade_once'][$id]=['nonce'=>bin2hex(random_bytes(32)),'expires'=>time()+600,'backup_readiness'=>$ready];$result='<p role="status">Verify Automatik: PASS. READY TO INSTALL. Backup database lengkap akan dijana dan disahkan sebelum fail diganti.</p>';}
     else $result='<p class="error" role="alert">Verify Automatik: BLOCKED. Pemasangan tidak dibenarkan.</p>';
    }elseif($action==='install'){
     $a=$_SESSION['upgrade_once'][$id]??null;unset($_SESSION['upgrade_once'][$id]);
     if(!is_array($a)||($a['expires']??0)<time()||!is_string($a['nonce']??null)||!hash_equals($a['nonce'],self::raw('nonce',64)))throw new \RuntimeException('Kebenaran install tamat atau tidak sah. Pakej kekal staged; sahkan Installation Key dan Verify Automatik semula.');
     InstallationKey::verify($p,$u,self::raw('key'));$s=$manager->installAutomatic($id,self::raw('password'),self::raw('core_approval',50)==='APPROVE SHARED CORE CHANGES');
     $result='<p role="status">INSTALLED — '.Support::escape($s['status']).'. Lengkapkan production smoke test sebelum release closure.</p>';
    }elseif(in_array($action,['activate','deactivate'],true)){InstallationKey::verify($p,$u,self::raw('key'));$manager->activation(self::raw('module',30),$action==='activate',self::raw('password'));$result='<p role="status">Status modul dikemas kini.</p>';}
    elseif($action==='download'){$manager->confirm(self::raw('password'));$kind=self::raw('kind',40);$file=$manager->download($id,$kind);header('Content-Type: '.(str_ends_with($kind,'.zip')?'application/zip':'application/json'));header('Content-Disposition: attachment; filename="'.($kind==='state.json'?'upgrade-report.json':$kind).'"');readfile($file);exit;}
    elseif(!in_array($action,['select','new_package','preflight'],true))throw new \RuntimeException('Tindakan tidak sah.');
   }
  }catch(\Throwable $e){$error=($e instanceof \RuntimeException&&!$e instanceof \PDOException)||$e instanceof \InvalidArgumentException?$e->getMessage():'Permintaan gagal. Rujukan '.Support::log($e);}
  $versions=Versions::read($p);$pass='<label>Sahkan kata laluan Super Admin<input type="password" name="password" autocomplete="current-password" required maxlength="72"></label>';$key=self::keyField('key','Installation Key (tepat 12 digit)');$confirm=self::keyField('key_confirm','Sahkan Installation Key');
  $runs=$manager->runs();$active=null;$selection=$_SESSION['upgrade_active_run']??null;foreach($runs as $r)if($r['id']===$selection){$active=$r;break;}
  if(!$active&&empty($_SESSION['upgrade_new_package']))foreach($runs as $r){if(version_compare($r['version'],$versions['app_version']??'0.0.0','>=')&&in_array($r['status'],['STAGED','PREFLIGHT','VERIFIED_LOCAL_INSTALL','RECOVERY_REQUIRED','BLOCKED'],true)){$active=$r;break;}}
  if($active){$_SESSION['upgrade_active_run']=$active['id'];unset($_SESSION['upgrade_new_package']);}
  $body='<div class="upgrade-version"><p>Versi semasa <strong>'.Support::escape($versions['app_version']??'unknown').'</strong> · Core '.Support::escape($versions['core_version']??'unknown').' · Training '.Support::escape($versions['module_version.training']??'unknown').'</p><p>Versi sasaran <strong>'.Support::escape($active['version']??'Pilih pakej ZIP').'</strong></p></div><ol class="upgrade-steps" aria-label="Langkah upgrade"><li>1. Upload ZIP</li><li>2. Verify Automatik</li><li>3. Install Upgrade</li><li>4. Selesai</li></ol>'.($error?'<p class="error" role="alert">'.Support::escape($error).'</p>':'').$result;
  if(!InstallationKey::configured($p))Support::layout('Versioned Upgrade',$body.'<section class="card"><h2>Create Installation Key</h2><p>Tepat 12 digit 0–9. Sifar di hadapan dibenarkan. Kod disimpan sebagai hash dan tidak dipaparkan semula.</p>'.Support::form('key_setup',$key.$confirm.$pass,'Create Installation Key').'</section>');
  $open=InstallationKey::authorized($p,$u);if(!$open)$body.='<section class="card"><h2>Pengesahan keselamatan</h2>'.Support::form('key_verify',$key,'Sahkan Installation Key').'<p>Pakej staged dikekalkan apabila kebenaran tamat. Tiada upload semula diperlukan.</p></section>';
  if($active){
   $id=$active['id'];$fields='<input type="hidden" name="run_id" value="'.Support::escape($id).'">';$report=$manager->report($id);$a=$_SESSION['upgrade_once'][$id]??null;$valid=self::fresh($report)&&is_array($a)&&($a['expires']??0)>=time()&&($a['backup_readiness']['status']??'')==='PASS';
   $status=$active['status']==='VERIFIED_LOCAL_INSTALL'?'INSTALLED':($valid?'READY TO INSTALL':(self::fresh($report)?'VERIFIED':$active['status']));
   $body.='<section class="card"><h2>'.Support::escape($active['module'].' '.$active['version']).'</h2><p role="status"><strong>'.Support::escape($status).'</strong></p>';
   if(in_array($active['status'],['STAGED','PREFLIGHT'],true)&&$open){if(!$valid)$body.=Support::form('preflight',$fields,'Verify Automatik');else $body.=Support::form('install',$fields.'<input type="hidden" name="nonce" value="'.Support::escape($a['nonce']).'">'.$key.(UpgradePolicy::ownerMode()?'':$pass).'<label class="upgrade-consent"><input type="checkbox" name="core_approval" value="APPROVE SHARED CORE CHANGES" required> Saya meluluskan perubahan Shared Core dalam pakej ini.</label><p>Backup database dan fail dibuat sebelum pemasangan. Hentikan cron dan aktiviti write lain sepanjang upgrade. Restore database ialah prosedur recovery berasingan.</p>','Install Upgrade');}
   if($status==='INSTALLED')$body.='<p>Upgrade selesai di server. Pengesahan production berautentikasi dan browser masih diperlukan; ini bukan baseline LOCKED.</p>';
   if(in_array($active['status'],['RECOVERY_REQUIRED','BLOCKED'],true))$body.='<p class="error">Pemasangan dihentikan. Rujuk laporan dan recovery; jangan padam lock untuk memaksa retry.</p>';
   if($open&&in_array($active['status'],['STAGED','PREFLIGHT'],true))$body.=Support::form('new_package','','Pilih pakej lain (staged kekal disimpan)');
   $body.='</section>';
  }
  if($open){$body.='<section class="card"><h2>System Baseline & Release</h2><p>Metadata sahaja. Fingerprint site mesti dipin melalui saluran yang diluluskan; baseline bukan bukti functional acceptance.</p>'.Support::form('baseline_verify','','Verify Current Baseline — browser') .Support::form('baseline_generate','','Generate Baseline').Support::form('baseline_download','','Download Baseline').Support::form('release_catalog','','Semak available releases');foreach($_SESSION['release_catalog']['releases']??[] as $r)$body.=Support::form('release_retrieve','<input type="hidden" name="module" value="'.Support::escape($r['module']).'"><input type="hidden" name="version" value="'.Support::escape($r['version']).'"><p>'.Support::escape($r['module'].' '.$r['version']).'</p>','Pilih release & Verify Automatik');$body.='<details><summary>One-time trusted release repository setup</summary>'.Support::form('release_configure',Support::fields(['catalog_url'=>['Signed catalog HTTPS URL','url',''],'package_base'=>['HTTPS package folder ending /','url',''],'password'=>['Reconfirm Super Admin password','password','']]),'Simpan approved repository').'</details></section>';}
  if($open&&(!$active||$active['status']==='VERIFIED_LOCAL_INSTALL'))$body.='<section class="card"><h2>Upload ZIP</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="'.Support::csrf().'"><input type="hidden" name="action" value="upload"><label>Pakej ZIP upgrade<input type="file" name="package" accept=".zip" required></label><p>SHA-256, manifest, polisi pemasangan dan compatibility diperiksa secara automatik. ZIP diluluskan oleh Super Admin; checksum bukan bukti penerbit.</p><button>Upload & Verify Automatik</button></form></section>';
  if(isset($_SESSION['baseline_verification']))$body.='<details><summary>Baseline verification details</summary><pre>'.Support::escape(json_encode($_SESSION['baseline_verification'],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</pre></details>';
  $body.='<details class="upgrade-advanced"><summary>Advanced Details &amp; Recovery</summary>';
  if($active){$body.='<h3>Technical report</h3><pre>'.Support::escape(json_encode(['run_id'=>$active['id'],'manifest'=>$active['manifest'],'preflight'=>$manager->report($active['id']),'backup_reference'=>$active['backup_reference']??null,'recovery'=>$active['recovery']??null],JSON_PRETTY_PRINT)).'</pre>';if($open)foreach(['state.json','preflight.json','files-backup.zip'] as $kind)$body.=Support::form('download','<input type="hidden" name="run_id" value="'.Support::escape($active['id']).'"><input type="hidden" name="kind" value="'.$kind.'">'.$pass,'Download '.$kind);}
  $body.='<h3>Upgrade history</h3>';foreach($runs as $r){$body.='<p>'.Support::escape($r['module'].' '.$r['version'].' · '.$r['status']).'</p>';if($open&&in_array($r['status'],['STAGED','PREFLIGHT'],true))$body.=Support::form('select','<input type="hidden" name="run_id" value="'.Support::escape($r['id']).'">','Sambung pakej '.$r['version']);}
  $body.='<h3>Installation Key</h3>'.Support::form('key_rotate',self::keyField('old_key','Installation Key lama').$key.$confirm.$pass,'Tukar kod').'<p>Recovery pentadbiran: php bin/platform.php key-recovery melalui Terminal. Sahkan Super Admin. Token sekali guna luput selepas 15 minit.</p>'.Support::form('key_reset','<label>Recovery token<input type="password" name="recovery_token" required maxlength="64" autocomplete="off"></label>'.$key.$confirm.$pass.'<label>Sebab recovery<input name="reason" required maxlength="500"></label>','Reset Installation Key').'<p>Retention backup: sekurang-kurangnya tujuh backup terbaharu; backup run yang dirujuk sentiasa dikekalkan. Hanya backup automatik tanpa rujukan berusia lebih 30 hari layak dipadam. Backup manual tidak dipadam.</p>';
  if($open)$body.=Support::form('activate','<label>Module key<input name="module" value="training" required></label>'.$key.$pass,'Activate Module').Support::form('deactivate','<label>Module key<input name="module" value="training" required></label>'.$key.$pass,'Deactivate Module');
  Support::layout('Versioned Upgrade',$body.'</details>');
 }
}
